["Worgen:04"]={["START"]=13.08, ["STOP"]=18.28, ["NAPIS"]="Gilneas hayatta kaldı, ancak İkinci Savaş\'ı takip eden kaotik yıllarda"}, 
["Worgen:05"]={["START"]=18.28, ["STOP"]=21.22, ["NAPIS"]="güçlü krallık giderek içine kapandı."}, 
["Worgen:06"]={["START"]=21.22, ["STOP"]=28.00, ["NAPIS"]="Eski müttefiklerine güvenmeyen Gilnealılar topraklarının sınırlarına muazzam bir duvar ördüler"}, 
