["Worgen:08"]={["START"]=33.50, ["STOP"]=41.20, ["NAPIS"]="Şimdi, yıllar sonra, görünüşte durdurulamaz olan ölümsüz Scourge Lordaeron\'a doğru ilerliyor,"}, 
["Worgen:09"]={["START"]=41.20, ["STOP"]=45.52, ["NAPIS"]="İnsan uygarlığı bir kez daha yıkımın eşiğine geldi."}, 
["Worgen:10"]={["START"]=45.52, ["STOP"]=48.96, ["NAPIS"]="Savaş ve terör etraflarını sararken,"}, 
["Worgen:11"]={["START"]=49.10, ["STOP"]=52.98, ["NAPIS"]="Gilneas halkı korkunç bir gerçekle yüzleşir;"}, 
["Worgen:12"]={["START"]=52.98, ["STOP"]=57.52, ["NAPIS"]="güçlü duvarları ölüleri daha fazla tutamaz."}, 
["Worgen:13"]={["START"]=57.52, ["STOP"]=62.24, ["NAPIS"]="Ve daha da kötüsü, krallığın sınırları içinde insan gibi dik yürüyen ama kurt gibi avlanıp uluyan"}, 
