    t[3433259862]="Azeroth'un ruhu,"
    t[4225812881]="Yaralı,"
    t[3191746230]="Savunmasız,"
    t[3397362334]="Ama yine de potansiyel dolu."
    t[3093286406]="Bu kusurlu gerçekliği ortadan kaldırmak için"
    t[802928823]="kullanacağım potansiyel."
    t[3867371689]="Ölüm, dünyanızın ruhunu ele geçiriyor."
    t[1073122979]="Şimdi tanık olun ölümlüler,"
    t[3939622755]="sonsuzluğun sonuna."
    t[3996046295]="Bu olmamalı."
    t[4188206510]="Hakemlik görevine ihanet ettin"
    t[2799103175]="ve sonsuza dek bağlı kalacaksın."
    t[2397652384]="Çılgınlığın tüm yaşam"
    t[1712767146]="ve ölüm döngüsünü tehdit etti."
    t[587073232]="[Denathrius] Başka bir yol"
    t[4163139157]="arayabilirdin, kardeşim."
    t[3414182014]="Birlikte neler başarabileceğimizi"
    t[1460220212]="bir düşün."
    t[127261318]="[The Primus] Neden, Zovaal?"
    t[2667545302]="Seni bu sona sürükleyen neydi?"
    t[3907938546]="Ölüme mahkum olanı korudunuz."
