    t[1424945892]="dayanamaz."
    t[4196692624]="[kasvetli koro müziği]"
    t[1254388722]="Arbiter Pelagos: Sylvanas Windrunner..."
    t[2573472802]="Arbiter Pelagos: Karar verme zamanınız geldi."
    t[1240563397]="Arbiter Pelagos: Merhamet olmadan gerçek adalet olamaz..."
    t[1597896140]="Arbiter Pelagos: ve yaptıklarınızın Jailer'ın etkisinin izlerini taşıdığını görebiliyorum."
    t[3748867272]="Arbiter Pelagos: Kontrol altına almayı başaramadığımız bir etki."
    t[1719430421]="Sylvanas Windrunner: Jailer beni kontrol etmedi."
    t[914587723]="Sylvanas Windrunner: Yaptıklarım sadece bana aitti ve sonuçlarını kabul ediyorum."
    t[1284788687]="Arbiter Pelagos: O zaman... kalbinizde kime cevap vermeniz gerektiğini biliyorsunuz."
    t[604598611]="Sylvanas Windrunner: Kararına boyun eğiyorum..."
    t[2017352722]="Sylvanas Windrunner: Tyrande Whisperwind'in."
    t[2841846920]="Arbiter Pelagos: Adaleti en ateşli düşmanına emanet ediyorsun."
    t[3027491934]="Arbiter Pelagos: Burada bu kadere itiraz edenler var mı?"
    t[2063477132]="Arbiter Pelagos: Öyle olsun."
    t[967919747]="Tyrande Whisperwind: Şimdi hangi oyunu oynuyorsun, Banshee?"
    t[3971021546]="Tyrande Whisperwind: Benim avladığım Sylvanas asla düşmanının kılıcına boyun eğmezdi."
    t[178194779]="Sylvanas Windrunner: Ölüm merhametli bir son olurdu, Tyrande."
    t[2891731848]="Sylvanas Windrunner: Ve senden merhamet beklemiyorum."
    t[3772584799]="Tyrande Whisperwind: Yeni keşfettiğin pişmanlığın gerçek olabilir..."
    t[102871309]="Tyrande Whisperwind: ama yaptıklarını asla silemez."
    t[2199976318]="Tyrande Whisperwind: Senin için barış olmayacak, Windrunner..."
    t[2203427751]="Tyrande Whisperwind: kurbanlarınızın ruhları huzura kavuşana dek."
    t[3273920859]="Tyrande Whisperwind: Mahkum artık benim sorumluluğumda."
    t[2249778172]="Tyrande Whisperwind: Getirin onu!"
    t[335264799]="Tyrande Whisperwind: Aşağıda Maw yatıyor."
    t[3632564254]="Tyrande Whisperwind: Pek çok kişiyi mahkum ettiğin adaletsiz bir kader."
    t[3743596498]="Tyrande Whisperwind: Ve kefaretin orada başlayacak."
    t[2350261416]="Tyrande Whisperwind: Her ruh kendi derinliklerinde kaybolur, ihanete uğrar ya da mahkum edilir..."
    t[927104752]="Tyrande Whisperwind: sen onları bulacak ve Arbiter'e göndereceksin"
    t[2760745703]="Tyrande Whisperwind: tüm ruhların hak ettiği şefkatle yargılansı için."
    t[4028387728]="Tyrande Whisperwind: Orada, Dori'thur'un dikkatli gözleri altında çalışacaksın,"
    t[981685284]="Tyrande Whisperwind: her karanlık yeri araştırıcak,"
    t[567705175]="Tyrande Whisperwind: ta ki son ruh özgür kalana ve geriye kalan tek şey sen olana dek."
    t[1626186871]="Tyrande Whisperwind: Kurbanlarına bu şekilde yenilenme getireceksin,"
    t[4002305330]="Tyrande Whisperwind: ve benim halkıma da."
    t[2259245661]="Sylvanas Windrunner: Ne kadar sürerse sürsün."
    t[1357897084]="Sylvanas Windrunner: bu yapılacaktır."
    t[3970212308]="Tyrande Whisperwind: Andu-falah-dor, eski dostum. Onu iyi izle."
