    t[1654156817]="adaların çağrısına"
    t[14945184]="cevap verdikten sonra."
    t[2391512294]="Bir şey oldu, Khadgar."
    t[3522188572]="Korkunç bir şey."
    t[4154504398]="Kalecgos..."
    t[631097258]="Anlat."
    t[1915268213]="Her şey çok çabuk oldu,"
