    t[2620646909]="Ne o?"
    t[509518914]="[Alexstrasza] O..."
    t[3240024836]="Raszageth."
    t[2547273827]="Primal enkarnelerin en genci."
    t[2865966952]="Enkarneler?"
    t[4006418358]="Elementsel güçlerin"
    t[1805255917]="dört tehlikeli yandaşı."
    t[1238903193]="Aspect'lerin doğuşuyla,"
    t[701490373]="uçuşlarımız titanların armağanlarını kucakladı."
    t[3475664910]="Onlar... yapmadılar."
    t[2450274344]="Ardından gelen savaş hayal bile edilemezdi,"
    t[1485168317]="ve onları sürgün etmek için"
    t[1439233271]="tüm gücümüzü birleştirmemiz gerekti."
    t[1604568569]="Madem bu kadar tehlikeliydiler,"
    t[2265818813]="neden yok edilmediler?!"
    t[79578053]="Bunu yapmaya yüreğim el vermedi."
    t[4192339882]="Bir zamanlar yumurta kardeşi gibiydik."
    t[1066138375]="Görünen o ki,"
    t[3797764213]="zaman onların öfkesini dindirmemiş."
    t[2792788946]="Ve bize bak."
    t[873589350]="Şimdi soydaşlarını serbest bırakırsa,"
    t[2011841785]="onları durduracak gücümüz yok."
    t[2965523530]="Ve eğer Iridikron'un açlığı serbest kalırsa..."
    t[1616039701]="Öyleyse başka seçeneğimiz yok."
    t[3638036300]="Eğer bir kez daha koruyucu olacaksak,"
    t[3166922196]="ejderha uçuşlarımızın aspect'leri"
    t[1724350940]="yeniden oluşturulmalı."
    t[602183344]="Kraliçemiz kararlı, Khadgar,"
    t[3807980128]="ama kendimizi yeniden keşfetmeye"
    t[3207869436]="ancak yeni başladık."
    t[12146149]="Ve korkarım ki yardım almazsak"
    t[96166631]="belki de geleceğimizi koruma şansını"
    t[2791362674]="asla yakalayamayacağız."
    t[3792393908]="Hmm..."
    t[488100846]="O halde ölümlü ırklar da"
    t[731149010]="çağrıya cevap vermeli"
    t[3735054073]="ve önlerindeki fırtınalarla yüzleşmeli."
    t[1012634139]="Kalecgos: Azure Arşivleri'ni güvence altına aldık, ancak Raszageth'in fırtınası Vakthros Kulesi'nin etrafını sarmaya devam ediyor."
    t[2630860775]="Alexstrasza: Soydaşlarını serbest bırakmaya çalışıyor ama onların hapishanesi Azure Span'da değil."
    t[3584481549]="Alexstrasza: Başka neyin peşinde olabilir ki?"
    t[1114524077]="Alexstrasza: Bu yumurtaya ne oldu?"
    t[4215661195]="Alexstrasza: Onu çevreleyen enerjiler..."
    t[2402161335]="Kalecgos: Şehir korunmalı."
    t[2432177730]="Kalecgos: Valdrakken halkımızın evi."
    t[4112431479]="Alexstrasza: Eğer Primalistler buradaysa, onları bulup dışarı çıkarmalıyız."
    t[2054641391]="Alexstrasza: Güç merkezimize sızmalarına izin veremeyiz."
    t[1417279290]="Alexstrasza: Şimdi o da tüm yemin taşları gibi uykuda."
    t[1781034785]="Yaşam Bağlayıcı Alexstrasza: Boyutsal gücümüzden vazgeçtiğimizde sessizleştiklerinden şüpheleniyorum."
    t[582440509]="Alexstrasza: Aspectral gücümüzden vazgeçtiğimizde sessizleştiklerinden şüpheleniyorum."
    t[3250619168]="Alexstrasza: Geride bıraktığımız o kadar çok şey var ki."
    t[3942895055]="Alexstrasza: Ama artık eve döndüğümüze göre, uçuşlarımızın çağrılarını yerine getirebilir ve beş yemin taşını yenileyebiliriz."
    t[1815786861]="Alexstrasza: Ve onların birliği sayesinde, yok olan gücümüz yeniden tesis edilecek."
    t[486724531]="[sakin, mistik müzik]"
    t[3184126049]="Bu tohum her şeydir."
    t[2615183119]="Bir çok sevgili ruh kaderlerini,"
    t[2529694318]="umutlarını bize emanet ediyor."
    t[2175783818]="Güvenli olacağından emin miyiz?"
    t[353258503]="[Merithra] Burada, Elune'nin lütfuyla,"
    t[404378076]="ona zarar vermek isteyenlerden"
    t[3386101471]="bu hediye saklı tutulacak."
    t[2877874971]="Yine de zamanı geldiğinde"
    t[2779091111]="rüyanın beşiğinden ayrılmalı"
    t[978116691]="ve dünyamızdaki yerini almalıdır."
    t[2665709763]="Ve bu gerçekleştiğinde,"
    t[1934653095]="onun korunması bize düşecektir."
    t[3333342309]="Sevgili Kaldorei."
    t[3729118399]="Tüm çektiğin acılar,"
    t[1709830560]="tüm fedakarlığın,"
    t[1270134478]="boşa gitmeyecek."
    t[2445691822]="Bunun için sana söz veriyorum."
    t[339060874]="Ne oldu, aşkım?"
    t[580083262]="Sadece bir his..."
    t[3624857342]="bu sefer farklı olacak."
    t[1903778258]="Fyrakk: Sonra o ağaç sayesinde tüm Azeroth yanacak."
    t[2920323028]="Fyrakk: Yine de başarısızlıklarınızı telafi etmek için gücümü boşa harcamamı mı istiyorsunuz?"
    t[3292143522]="Gangshe: Ben sadece..."
    t[535649823]="Gangshe: Bağışlayın beni. Bu bariyeri yıkacağız."
    t[375248317]="Fyrakk: Hayır. Sen değil."
    t[3410731652]="Tyrande Whisperwind: Bunu benden isteme."
    t[2936633701]="Tyrande Whisperwind: Yaşadığımız onca şeyden sonra..."
    t[2176989628]="Malfurion Stormrage: Aşkım benim."
    t[1205898599]="Malfurion Stormrage: Sen her zaman halkımızın gücü oldun."
    t[2405293654]="Malfurion Stormrage: Seni daima takip edecekler ve asla yalnız kalmayacaksın."
    t[3328006415]="Tyrande Whisperwind: Seni tekrar görene kadar..."
    t[1471656988]="Tyrande Whisperwind: Gerçekten dinlenebileceğimiz geceyi düşleyeceğim... birlikte."
    t[2507396734]="Merithra: <Ağır nefes alıyor>"
    t[1984959540]="Merithra: Anne..."
    t[2879835273]="Merithra: <İç çeker>"
    t[3923163911]="Tyrande Whisperwind: Yıldızların çocukları,"
    t[1588186177]="Tyrande Whisperwind: Bu ana kadar uzun bir yolculuk oldu."
    t[464682105]="Tyrande Whisperwind: Halkımız savaştı, acı çekti ve çok şey feda etti."
    t[4233421766]="Tyrande Whisperwind: Ve yine de burada, Amirdrassil'in genç dallarının gölgesinde,"
    t[4085075102]="Tyrande Whisperwind: sonunda iyileşmeye başlayabiliriz."
    t[1980715642]="Tyrande Whisperwind: Şimdi bu kutsal yere göz kulak olan ruhlara,"
    t[4142360188]="Tyrande Whisperwind: kutsamalarımızı sunuyoruz."
    t[2398230650]="Tyrande Whisperwind: Adanmışlık, güç ve sevgi sembolleri."
    t[1500571364]="Tyrande Whisperwind: Bu ay kuyusuna bu değerli şişeyi sunuyoruz,"
    t[1997423612]="Tyrande Whisperwind: Darnassus tapınağından kurtarılan son sular."
    t[1496831601]="Tyrande Whisperwind: Amirdrassil'i Elune'nin ışıltısıyla yıkasınlar,"
    t[272334665]="Tyrande Whisperwind: ve onun kutsamalarını bu yere bağışla--"
    t[2296320063]="Tyrande Whisperwind: Bel'ameth tanrıçanın kollarında."
    t[1037711474]="Tyrande Whisperwind: Onun kucağında, kaldorei sonunda huzuru bulsun."
    t[1666407044]="Tyrande Whisperwind: Elune-adore."
    t[1013043512]="Hayat-Bağlayıcı Alexstrasza: Bu zamanı birlikte geçirdiğimiz için çok minnettarım."
    t[3525271231]="Ysera: Sevgili dostlarım."
    t[1450575736]="Ysera: Burada toplananların yardımıyla,"
    t[2638155414]="Ysera: Amirdrassil etrafımızda çiçek açıyor."
    t[1558523527]="Ysera: Tohumunu kollarında ilk tuttuğun zamanı hatırlıyor musun, Tyrande?"
    t[1286742079]="Tyrande Whisperwind: Elbette hatırlıyorum."
    t[1928948461]="Tyrande Whisperwind: Onu bir çocuk gibi kucağıma almıştım,"
    t[3025351130]="Tyrande Whisperwind: ve içindeki ruhlara söz verdi"
    t[835752886]="Tyrande Whisperwind: Fedakarlıklarını onurlandırmak için."
    t[1682611008]="Ysera: Ve sana yemin ettim"
    t[1924650504]="Ysera: Onu korumak için elimden gelen her şeyi yaparım."
    t[4138978133]="Ysera: İkimiz de yeminlerimizi tuttuk."
    t[2310061099]="Ysera: Ardenweald'a dönme vaktim geldi,"
    t[3584484689]="Ysera: dengeyi sağlamak,"
    t[1543833361]="Ysera: ve eski bir dosta borcumu ödemek için."
    t[4126847719]="Merithra: Geri geleceğini sanıyordum--"
    t[2548617465]="[elektri̇k çatırdaması]"
    t[3946494505]="[yoğun nefes alma]"
    t[2653482643]="Onu durdurduk."
    t[246236980]="[elektri̇k çatırtısı yoğunlaşıyor]"
    t[2296671279]="Hayır... Hasar çok büyük!"
    t[3581944279]="Onlar hakkında..."
    t[1508232162]="[Vyrannoth] Kardeşim."
    t[1462844706]="Sana ne yaptılar?"
    t[2178762919]="[Fyrraka] Onun ölümü intikam gerektiriyor!"
    t[1211736760]="[patlama]"
    t[1348366703]="[Iridikron] Ejderha türüne"
    t[1750110561]="titanlara ihanet eden"
    t[1119899236]="herkes gazabımızla yüzleşecek."
    t[4183784904]="Khadgar, bu savaşı kazanamayız."
    t[4100483467]="Buradan gitmeliyiz!"
    t[4272963676]="Nozdormu: Onlar... kaotik, ama yine de gizlenmişler."
    t[4275161907]="Alexstrasza the Life-Binder: Güçlerini yeniden kazanacaklar ve bir sonraki anlarını dikkatle seçecekler."
    t[4271546328]="Alexstrasza the Life-Binder: Sonunda, davalarını canlı tutmak için korkunç pazarlıklar yaptı."
    t[3143350743]="Kalecgos: Müttefiklerimizi kucaklayalım."
    t[432927855]="[dramatik, orkestral müzik çalıyor]"
    t[1202432418]="[Alexstrasza] Raszageth, yeter!"
    t[3767605316]="Başka bir savaşa girmemize gerek yok."
    t[154711187]="Mantıklı düşünmek için hâlâ zaman var."
    t[2665179208]="[Raszageth] Zaman tam olarak"
    t[1494536518]="benden çaldığın şey."
    t[160729201]="Binlerce yıldır,"
    t[935712214]="o hapishanede çürüyordum."
    t[3414100883]="[Alexstrasza] O zaman aramızdaki barışı"
    t[602373043]="sağlamayı başaramadım."
    t[269500630]="Bunun için çok fazla ödeme yapıldı."
    t[2999642337]="[Raszageth] Bana kutsallık taslama!"
    t[2810992139]="Titanların fermanlarını hepimize zorla kabul ettirdin."
    t[206885490]="Bize hayat veren dünyaya ihanet ettin"
    t[312283333]="ve direnmeye cesaret ettiğimizde,"
    t[554095991]="Bizi dışarı attın!"
    t[3997297182]="[gök gürültüsü]"
    t[857359132]="Bir daha asla!"
    t[231646836]="[Raszageth kükrer]"
    t[2732570181]="[her ikisi de hırlıyor]"
    t[1853020976]="[epik, orkestral müzik çalıyor]"
    t[2978826831]="[hırıltı ve çatırtı]"
    t[3508148573]="[ejderha homurdanıyor]"
    t[228178505]="[hırıltılar]"
    t[2074951475]="[çıtırtı]"
    t[1496202673]="[düşük hırıltı]"
    t[1339123795]="Sahte saltanatın sona ermeli!"
    t[4183693308]="[yumuşakça hırlıyor]"
    t[2777896318]="[Alexstrasza] Wrathion?"
    t[2140891152]="[Raszageth homurdanıyor]"
    t[1088485704]="[Raszageth] Ah."
    t[1159199432]="Çok cesursun ejderha yavrusu,"
    t[25581959]="ama yanlış tarafta savaşıyorsun."
    t[3856475460]="Bize çektirdikleri acıları,"
    t[3425693838]="unutulmanın verdiği hakareti"
    t[2275140918]="size hiç anlatmadı."
    t[162504883]="İnşa ettiği her şeyin"
    t[57510917]="yıkılışını"
    t[370002518]="çaresizce izlemesini istiyorum."
    t[4112348114]="Ancak o zaman"
    t[3535712196]="uygun bir sonla karşılaşacak."
    t[2881263067]="[müzik durur]"
    t[1911794237]="Alexstrasza the Life-Binder: Wrathion, sana minnettarım."
    t[944448145]="Alexstrasza the Life-Binder: Yardımınız... beklenmedikti, ama takdir edildi."
    t[2639290337]="Wrathion: Yanınızda durmak bir onurdu Kraliçem."
    t[704153561]="Wrathion: Uçuşunun Obsidian Kalesi'ni djaradin'den almamızda bize yardımcı olacağına inanıyorum."
    t[4256823324]="Alexstrasza the Life-Binder: Elbette yapacağız... yumurtaların güvenliğini sağladıktan sonra."
    t[2935133633]="Wrathion: Raszageth kovulduğu için güvende olduklarına eminim."
    t[2335631561]="Alexstrasza the Life-Binder: Onu benim kadar tanımıyorsun, genç adam."
    t[171212915]="Alexstrasza the Life-Binder: O tahmin edilemez bir düşman."
    t[2632167578]="Alexstrasza the Life-Binder: Şimdilik, Yaşam Havuzları'nda kalmalı ve geleceğimizi korumalıyız."
    t[3102567508]="Wrathion: Bizim geleceğimiz mi? Yoksa sizin mi?"
    t[1687074870]="Wrathion: Obsidyen Hisarı, tüm Ejderha Adalarını savunmak için inşa edildi."
    t[3961863538]="Wrathion: Kaçışımın mirasını düşmanlarımızın eline bırakamazsın."
    t[701489910]="Alexstrasza the Life-Binder: Çaresiz yumurtaların korunmasına daha fazla önem vermeni beklerdim, Wrathion."
    t[3414098482]="Wrathion: Kal o zaman."
    t[1214577298]="Wrathion: Uçuşunuz için en önemli olanla ilgilenin, ben de benim için en önemli olanı kurtarayım."
    t[2632046193]="(Emberthal) [yoğun bi̇r şeki̇lde nefes veri̇r]"
    t[1976274987]="Nozdormu, bekle."
    t[2674654446]="Bana hep yol gösterdin"
    t[1849813624]="zamanın her anında,"
    t[3944427558]="şimdi de benden sana rehberlik etmemi mi istiyorsun?"
    t[773126943]="Gördüklerimde kör bir nokta var"
    t[210023388]="Neltharian'ın yozlaşmasından önceki zamana dair"
    t[1957442718]="ve bunun senin üzerinde yoğunlaştığına inanıyorum."
    t[100450570]="Nedenini bilmeliyim."
    t[484105281]="Wrathion: Sanırım yanılıyorsunuz. Bu taht, bu miras benim doğuştan hakkım."
    t[1544861792]="Sabellian: Hayır. Hata senin. Bu uçuşun bekçisi olarak bizzat Neltharion tarafından görevlendirildim."
    t[2475013446]="Sabellian: Açık konuşayım... Her şey söylendiğinde ve yapıldığında, ben siyah dragonflight'ın Aspect'i olacağım."
    t[3300687310]="Wrathion: Öyle mi? En değerli ejderha kazansın."
    t[3406084508]="Alexstrasza: Sonunda, kayıp gençlerimiz bir kez daha aramızda, böylece tüm uçuşlarla birlikte yetiştirilebilirler."
    t[3874507790]="Alexstrasza: Bu Yaşam Havuzları bir zamanlar yumurtadan yoksun olsalar da, şimdi geleceğimizi içlerinde barındırıyorlar."
    t[466108412]="Alexstrasza: Gerçekten de uçuşumun çağrısı yerine getirildi."
    t[1181547432]="Mother Elion: Bu yumurtaların korunduğunu ve sevildiğini göreceğim."
    t[3031552600]="Mother Elion: Böylece güçlü ve bilge ejderhalara dönüşebilirler."
    t[3797060682]="Khanam Matra Sarest: Eğer Ohn'ahra isterse, yarın Drusahl'ın Borusu'nu çalarak yeşil dragonfight ile anlaşmamızı işaret edeceğim."
    t[3952105083]="Onu hafızanda ara."
    t[2067696619]="Gemisath: Ysera'nın kızı Merithra, minnettar..."
    t[681329747]="Balakar Khan: Minnettar mı? Ha! Ejderhalar sadece ejderhalara saygı duyar."
    t[3625994347]="Balakar Khan: Onlar için hiçbir Maruuk kanı akıtılmayacak."
    t[1229069100]="Khanam Matra Sarest: Khanam Matra sen değilsin, Balakar."
    t[507315284]="Balakar Khan: Gerçek bir lider bu toprakları asla yabancılara teslim etmez."
    t[4225829307]="Balakar Khan: Maruuk Thousandbones'un hatırasını kirletiyorsun, Sarest."
    t[2918853474]="Khanam Matra Sarest: Geri çekil!"
    t[3569987806]="Balakar Khan: Hayır. Bu ovalar Maruuk'a ait."
    t[4011519268]="Balakar Khan: Ve Maruukai de Nokhud'a ait!"
    t[1063198127]="Koroleth: Dur!"
    t[781727035]="[Emberthal] [yankılanıyor] Generalim."
    t[2531900261]="Initiate Boku: Uzak dur... yapma..."
    t[1786358258]="Koroleth: Maruuk'un bir mistiği için geçen bu mu?"
    t[1305206756]="Initiate Boku: Ohn'ahra. Özür dilerim."
    t[2496057301]="Koroleth: Acınası."
    t[1572589320]="Koroleth: Neredeyse orada...."
    t[1660074400]="Koroleth: Şimdi!"
    t[1322962178]="Gerithus: Anne!"
    t[149371479]="Koroleth: Rüzgarlar bizi ileriye taşısın! Zümrüt Bahçeleri düşecek!"
    t[856935836]="Boku: Şu taş sütunları görüyor musun? Onlar herhangi birinin yaklaşmasını engelleyen bir bariyerin parçası. Onları korumalıyız, yoksa adanın savunması düşecek."
    t[959735022]="Merithra: Görüyor musun? O pilonlar Koroleth'in yıkıcı gücünü artırıyor. Eğer onu durduramazsak sütunu yok edecek ve Ancient Bough'u koruyan muhafaza çökecek!"
    t[4099103014]="Şiddetli bir savaş. Ve sonra ben..."
    t[2319108475]="Khanam Matra Sarest: Ben, Khanam Matra Sarest, en kutsal atamızın ettiği kadim yemini onurlandırmak için bu hediyeyi kabul ediyorum."
    t[3785958150]="Khanam Matra Sarest: Ohn'ahra'nın kanatları altındaki tüm sentorlar ihtiyaç anında yeşil ejderha uçuşuna yardım edecektir."
    t[1367157672]="Merithra: Ve ben, Ysera'nın kızı Merithra, atanız Teera'ya olan yeminimi onurlandırmak için bu hediyeyi kabul ediyorum."
    t[3824517423]="Merithra: Ejderhalar ve sentorlar birlikte Ohn'ahran Ovaları'nı koruyacak."
    t[2998446342]="Khanam Matra Sarest: Rüya tekrar tehdit edilirse, Maruuk'un senin yanında savaşacağını bil."
    t[510122401]="Merithra: Geçmiş çağlarda bizi birleştiren bağ yenilendi."
    t[480284429]="Merithra: Bu yemin taşı antlaşmamızın bir sembolü olsun."
    t[3415307673]="Merithra: Zümrüt Rüyayı ve yeşil ejderha uçuşunu hayatım pahasına koruyacağıma yemin ederim."
    t[4246300126]="Bir tabura komuta etmek benim için onurdu."
    t[3041983758]="Neltharion'un vasiyetini tam olarak yerine getirdik."
    t[594278734]="Bağlılığımız ve disiplinimiz"
    t[1713308729]="eşsizdi."
    t[1448329546]="[Nozdormu] Bir Titan eseri!"
    t[195629753]="Birliğinizin kaynağı bu olmalı."
    t[2856992599]="Bu, sizi onun iradesine bağlayan"
    t[2572385116]="kadim bir sihirdi."
    t[714662417]="Onun kaprisi karşısında"
    t[833887947]="kendinizi feda etmez misiniz?"
    t[3566473501]="[Emberthal] Biz askerdik!"
    t[2838762397]="Dünya için birçok tehdit vardı."
    t[1907441449]="[şi̇mşek çakiyor]"
    t[202075970]="[Emberthal] Ve işte en büyüğü:"
    t[1569435492]="Primalistler."
    t[509470370]="[Nozdormu] Bu Raszageth,"
    t[3984259863]="Fırtına Yiyen..."
    t[2566166340]="Primalist isyanın"
    t[3510023248]="liderlerinden biri."
    t[1209490162]="[Emberthal] Uyarı yapmadan saldırdılar."
    t[1370601612]="Onursuzca."
    t[2965282648]="Ve bu gün birçok arkadaşımı kaybettim."
    t[2520694125]="Geri çekildik, yeniden toplandık."
    t[2846733470]="Ama sonra..."
    t[3182131624]="her şey karmakarışık oldu, kafam karıştı."
    t[3875315906]="[Nozdormu] Obje... yok edildi."
    t[2677917788]="Ve dracthyr'i birleştiren"
    t[1206734501]="düzen büyüsü yok oldu."
    t[1343459115]="O zaman Raszageth nasıl yenildi?"
    t[1420384300]="İşte kardeşim, bizden sakladığın şey bu:"
    t[4001671412]="O an lütuftan düşmüştün."
    t[4030962282]="Çaresizlik içinde,"
    t[1432101810]="en derin kötülüğe yöneldi:"
    t[1182500213]="Eski Tanrıların gücüne."
    t[2504888799]="Keşke bilseydik..."
    t[2265347408]="[Emberthal] Ama o zaman..."
    t[4237115297]="neden hapsedildik?"
    t[3790849971]="Neden bu kadar uzun süre uyuduk?"
    t[3777046227]="Dracthyr'i artık"
    t[560218044]="kontrol edemiyorsa,"
    t[1398088415]="seni bir risk olarak görecekti."
    t[730464592]="[Emberthal] Hayır. Biz onun için hayatımızı ortaya koyduk."
    t[121430830]="O bizimle gurur duyuyordu!"
    t[126398913]="Neden bu kumu durdursun ki!"
    t[3980802303]="Göremiyorum!"
    t[421850094]="Çünkü sen istemiyorsun!"
    t[1508878957]="Ancak geçmişinizle yüzleşirsen"
    t[636027656]="olduğundan daha fazlası olabilirsin!"
    t[1922213869]="[sessizlik]"
    t[2249210258]="[derin yankılanma]"
    t[2541824146]="Bu yüzden bizi kilitledi."
    t[3103266749]="Varlığımızı bile unuttunuz."
    t[3264999301]="Bizi basitçe yok etmek"
    t[3036926962]="daha nazik bir davranış olurdu."
    t[3749374008]="Üzgünüm, genç dostum."
    t[2973709020]="Gerçeği bilmemiz gerekiyordu."
    t[2557156741]="Ama umutsuzluğa kapılma."
    t[2360455921]="Artık Neltharion'un"
    t[3223929774]="seni olabileceğin şey yüzünden"
    t[1813695808]="kilitlediğine inanıyorum."
    t[1740920861]="[Emberthal] Onun kontrolü olmasaydı"
    t[3966033720]="neler başarabilirdik."
    t[1436330424]="Ve artık özgürsünüz."
    t[2880589713]="Bu dünyanın sunacağı çok şey var,"
    t[926360718]="ve gelecekteki olaylarda sizin de"
    t[1404910601]="oynayacak bir rolünüz olacak."
    t[2886858574]="[Emberthal] Eski bir düşmanın"
    t[842905403]="dönüşünden bahsettin."
    t[1047229919]="Raszageth ve Primalistler."
    t[4265671894]="İşte bu yüzden uyandık."
    t[3127107616]="Görünüşe göre Neltharion'un"
    t[3917614156]="senin için bir planı varmış."
    t[4120198142]="Ama o gitti."
    t[649297597]="Hangi yoldan gideceğinize, hangi hikayeyi"
    t[1195572464]="anlatacağınıza karar vermelisiniz."
    t[803630149]="[Emberthal] Benim hikayem... benim olacak."
    t[4223905575]="[müzik kreşendoya yükselir]"
    t[2554492562]="Wrathion: Kimsin sen?"
    t[4050056998]="Sabellian: Sabellian, Neltharion'un varisi. Ya sen?"
    t[3303351377]="Wrathion: Wrathion, Neltharion'un varisi. Ve ben seni hiç duymadım."
    t[733814124]="Sabellian: Aynı şekilde."
    t[1526951195]="Sabellian & Wrathion: Bunu daha sonra tartışacağız."
    t[3712211964]="Wrathion & Sabellian: Bunu sonra tartışırız."
    t[123784242]="Wrathion: Sabellian? O ne yapıyor?"
    t[1544429314]="Sabellian: Ah, genç Wrathion. Sana teşekkür borçluyum--"
    t[2268097368]="Sabellian: Obsidyen Taht'taki haklı yerimi korumamda yardımın çok değerliydi."
    t[2738698083]="Pençeler! İleri!"
    t[3964268776]="Benimle kal. Yan tarafa! Kımıldayın!"
    t[3817550550]="Ebon Scales! Geri çekilin!"
    t[906248916]="Geri çekilin!"
    t[3422880452]="[Yankılanan ses] Uyku..."
    t[572330483]="Scalecommander Azurathel: Cindrethresh!"
    t[203629349]="Scalecommander Azurathel: Bu bariyeri yıkabilir misin?"
    t[2132305430]="Scalecommander Cindrethresh: Zury!"
    t[2358707549]="Scalecommander Cindrethresh: Tam da ihtiyacım olan takviye!"
    t[3672310901]="Scalecommander Azurathel: Earth-Warder'ı buldunuz mu?"
    t[4044093892]="Scalecommander Cindrethresh: Hayır. O bu odada değil."
    t[451482243]="Scalecommander Cindrethresh: Ama orada--"
    t[2437127945]="Scalecommander Azurathel: ...Farklı bir ejderha."
    t[2830430318]="Lapisagos: Gelin, Malygos'un sadık hizmetkarları!"
    t[1677864339]="Lapisagos: Bu sapkınlara merhamet göstermeyin!"
    t[4119589014]="Scalecommander Cindrethresh: Bu eğlenceli olacak!"
    t[1760770588]="Chromie: Neredeyse bitti!"
    t[3964207152]="Chromie: Tamam millet!"
    t[3857264711]="Chromie: Hazır ol!"
    t[2864536946]="Chromie: Hayır, yapamazsın!"
    t[1977295456]="Nozdormu: İmgelemim çok geç geldi."
    t[1591715934]="Nozdormu: Zamanda bir tünel açtılar ve sonsuz olasılıklar arasında sonsuza dek yuvarlanıyorlar."
    t[2580150044]="Nozdormu: Gerçekliğin tüm dokusu parçalanmadan önce onları bulmalı ve rotalarını düzeltmelisiniz."
    t[4185387469]="Ebyssian: Daha fazlasını yapmalıydım."
    t[1387321772]="Emberthal: Sen neden getirmedin?"
    t[3201198440]="Ebyssian: Çünkü ben de Neltharion'un çocuğuyum ve bu bana sadece utanç getirdi."
    t[678707650]="Ebyssian: Bununla yüzleşmek için geldim ve seni buldum."
    t[2799265829]="Emberthal: Hayal kırıklığına uğramış olmalısın."
    t[1589848280]="Ebyssian: Hayır. Az önce, onun içindeki sesine karşı geldin."
    t[1567083556]="Ebyssian: Şiddet yerine merhameti seçin."
    t[1940359103]="Ebyssian: Ailemiz onun gölgesinde yaşamak zorunda değil."
    t[1475243929]="Emberthal: Aile."
    t[1028476328]="Emberthal: Uyandığımda... hepsi gitmişti... hepsi."
    t[3242199967]="Emberthal: İlk defa yalnızdım. Ve bu beni dehşete düşürdü."
    t[3944131496]="Emberthal: Ve Sarkareth diğerlerini öldürdüğünde."
    t[2239560907]="Ebyssian: Emberthal."
    t[1853977790]="Ebyssian: Yaptığı şey için adaletle yüzleşecek."
    t[1787831649]="Emberthal: Bana yardım edecek misin, Ebyssian?"
    t[1516758148]="Ebyssian: Biz... birbirimize yardım edeceğiz."
    t[6554174]="Onun katillerinin"
    t[1263528773]="kalplerini yiyip bitirmeliyiz."
    t[349500421]="Onları hafife alma, Fyrakk."
    t[803729760]="Kardeşimizin aşırı güveni"
    t[2060319979]="onun çöküşü oldu."
    t[1046249131]="Aspect'lerin gücü azalırken,"
    t[411083559]="onların güçleri daha da artıyor."
    t[613575649]="Ve dengeleri eşitlemeliyiz."
    t[3835901107]="[köpüren enerji yoğunlaşıyor]"
    t[1705938226]="[enkaz takırtıları]"
    t[819776082]="Çok fazla sır sakladılar..."
    t[2867324800]="bizden,"
    t[2606269272]="ve hatta birbirlerinden."
    t[3276126522]="[lav köpürüyor]"
    t[3049179464]="[dramati̇k müzi̇k devam edi̇yor]"
    t[1598963023]="[şiddetli gümbürtü]"
    t[374175875]="[tehditkar bir şekilde güler]"
    t[1715222735]="İşte burada."
    t[1297565238]="Neltharion'un ihaneti"
    t[157367175]="birliklerini parçaladı..."
    t[3222482863]="kalplerinde çatlaklar bıraktı."
    t[1452479341]="[klank]"
    t[2390083433]="Yine de verdiği acı"
    t[1059017786]="sadece başlangıçtı."
    t[3106933560]="[enerji patlamaları, vızıltılar]"
    t[4090048929]="Aberrus..."
    t[3458942071]="onun gizli laboratuvarı."
    t[3719023509]="Son bir sır, toprağın derinliklerinde."
    t[980807199]="[Vyranoth] Aberrus'un yeri"
    t[3610318989]="bu geminin içinde olmalı."
    t[1753011662]="Onun bilgisini deşifre edeceğim."
    t[2294782358]="Neltharion'un"
    t[4247061834]="çarpık deneylerinin bize ne faydası var?"
    t[2661938739]="Laboratuvarın kendisinin"
    t[2075668974]="bir önemi yoktur."
    t[1287220342]="Ama ona... güç veren erimiş ateşi"
    t[591866077]="kullanabiliriz."
    t[1421196060]="Gözünü onlardan ayırma, Dezran."
    t[2065813036]="Neltharion'un mirasından geriye ne kaldıysa,"
    t[3538921985]="bize ait."
    t[1362816886]="[müzik şiddeti, azalır]"
    t[81184072]="Talon Damos: Güzel. Sen buradasın."
    t[3897840130]="Talon Damos: Bir daha asla kreşe adımımı atmam."
    t[871163241]="Talon Damos: Emberthal sizi içeride bekliyor."
    t[2760733018]="Talon Damos: Oh, ve... (boğazını temizler)... teşekkür ederim. Bize yardım ettiğiniz için."
    t[2900693615]="Scalecommander Emberthal: Damos senden övgüyle bahsediyor."
    t[2737248517]="Scalecommander Emberthal: Sık sık yaptığı bir şey değil."
    t[1243222752]="Scalecommander Emberthal: O ve diğerleri cevaplar arıyor... tüm bunlar için bir neden."
    t[2400392037]="Scalecommander Emberthal: Olan her şeyden sonra, yaşadığımız her şeyden sonra."
    t[2637225279]="Scalecommander Emberthal: Acaba aradığım şey... burada değil mi diye düşünmeye başlıyorum."
    t[179901691]="Talon Damos: Emberthal!"
    t[685715648]="Talon Damos: Aagugh!"
    t[2752827864]="Scalecommander Emberthal: Oh hayır... Hayır..."
    t[2584338415]="Talon Damos: (ölüm çıngırağı)"
    t[3504953947]="Scalecommander Sarkareth: Defolun. Burası Sundered Flame'e ait."
    t[1845170865]="Scalecommander Emberthal: SARKARETH!"
    t[2071557749]="Scalecommander Emberthal: (Nefes verir)"
    t[1094730868]="Scalecommander Emberthal: Damos..."
    t[1490947624]="Scalecommander Emberthal: Çok özür dilerim."
    t[936759033]="Scalecommander Emberthal: (Ağır nefes alıp verme, kederin öfkeye dönüşmesi, kararlılığın artması)"
    t[3573476362]="Ebyssian: Onu takip etseydiniz... ne yapardınız?"
    t[3726137582]="Morchie: Bu Morchie, seni velet. Ve evet! Murozond'u getirmenin zamanı geldi!"
    t[743461399]="Ebyssian: Neltharion adına."
    t[293870557]="Ebyssian: Ama bu sefer, \"düşman\" sizden biri,"
    t[316532291]="Ebyssian: Tıpkı onu takip eden Dracthyr gibi."
    t[160561928]="Ebyssian: Sizin gibi, ne pahasına olursa olsun zafer kazanmaya şartlanmış askerler."
    t[3024762250]="Emberthal: Bizi tanımaya nasıl cüret edersin?"
    t[18542661]="Emberthal: Diğer ejderhalar dünyamızı korumak için savaşıp ölürken sen ölümlülerin arasında saklandın!"
    t[3446523265]="Ebyssian: Haklısın."
    t[1256535423]="Ebyssian: Ben sadece \"Ebonhorn\" olmaktan memnundum ve Highmountain benim evimdi."
    t[4157670827]="Shikaar bölgesine izinsiz girdiniz!"
    t[3866707687]="açıkla..."
    t[2185099501]="Burada bulacağımızı söylemiştin."
    t[3605505341]="Yazdığım kadarıyla,"
    t[4182941157]="Bu tepenin hemen altında."
    t[1092799488]="Fyrakk: Primalistler! Zaqali! İlerleyin! BU MAĞARAYI TEMİZLEYİN -- VE SONRA, EJDERHA ADALARINI!"
    t[3963646450]="Sabellian: Loamm..."
    t[873057]="binlerce yıldır bozulmamış."
    t[225251466]="Fyrakk, aşağıdaki elemental güçle"
    t[130289224]="Yaşlıları uykularından uyandırın"
    t[2329086594]="Sabellian: Gördün mü, Wrathion? Biz oyalanırken onlar savunma hazırlıyorlardı."
    t[1629298694]="Sabellian: Wrathion?"
    t[681537134]="Wrathion: Sen de duydun mu? Bir ses--"
    t[1510947884]="Sabellian: WRATHION!"
    t[739136558]="Sabellian: Dikkatinizi verin!"
    t[4067282946]="Wrathion: Evet! Evet! Tabii ki."
    t[2174851116]="Wrathion: Bu Primalistlerin hiç şansı yok."
    t[3747796992]="Wrathion: Ugh! Botlarım çamur içinde. İğrenç!"
    t[2226568157]="Sabellian: Hah! İtiraf etmeliyim, Wrathion. Dövüşte kendini iyi akladın!"
    t[1602721283]="Wrathion: Şey, ben... Teşekkür ederim, Sabellian."
    t[3850999416]="Sabellian: Bu alevin vücut bulmuş halini hallettikten sonra, birliklerimin arasında sana da bir yer bulacağımdan emin olabilirsin."
    t[380266110]="Wrathion: Askerlerin mi?!"
    t[3140626280]="Wrathion: Sabellian!"
    t[1383345077]="Elder Honeypelt: Yapacağım."
    t[2286563307]="Elder Honeypelt: Anahtar, onları on tonluk bir kristalle tam doğru noktadan vurmak."
    t[2858176274]="Elder Honeypelt: Hnhk!"
    t[1486166487]="Elder Honeypelt: Oof! Bu gece eklemlerim ağrıyacak. Neyse..."
    t[1863005494]="Elder Honeypelt: Buralarda yeniymişsin gibi görünüyorsun."
    t[2170026549]="Elder Honeypelt: Hoş geldin, uplander! Ben Honeypelt."
    t[1543793311]="Scalecommander Sarkareth: Hayır! Oathbinder... BENİM!"
    t[2432614825]="Emberthal: Buraya bunun için mi geldin? Neltharion'un cihazlarıyla bizi tekrar köleleştirmek için mi? Birliği böyle mi kuracaktın?"
    t[3684143435]="Scalecommander Sarkareth: Ne... yaptın?"
    t[2003897232]="Scalecommander Sarkareth: Babam bize sesleniyor, Emberthal! Neltharion'ın bizi Aberrus'a çektiğini duymuyor musun? Bizim olanı almamızı mı söylüyor?"
    t[3739334424]="Emberthal: İyi değilsin Sarkareth... Benimle gel. Belki Ebyssian..."
    t[2134159138]="Scalecommander Sarkareth: Hayır! Bize vaat edilen mirası talep edeceğim! VOX, taşımayı başlat!"
    t[1527697037]="VOX: Koordinatlar onaylandı. Taşıma başlatılıyor."
    t[1848223051]="Emberthal: Sarkareth, bekle!"
    t[2826568736]="Emberthal: ...Gitti. Ben... hiçbir şey başaramadım."
    t[2384057763]="Ebyssian: Bu henüz bitmedi. Nereye gittiğini biliyor musun?"
    t[556461031]="Emberthal: Ebyssian... Neltharion'ın sesini duyduğunu söyledi. Aberrus'a gidiyor!"
    t[3352902762]="Ebyssian: Karanlıkta fısıltılar. Bu düşündüğümden daha kötü olabilir."
    t[3763467775]="Ebyssian: Ama en azından buradaki dracthyr'lar artık onun kontrolü altında değil."
    t[3002824573]="Wrathion: Ah, sevgili dostlarım. Bana ne hazineler getirdiniz?"
    t[716413817]="Sabellian: Onu görmezden gelin. Babamın eşyalarına hiçbir hakkı yok."
    t[2842950624]="Ebyssian: Gerçekten mesele bu mu?"
    t[996202998]="Ebyssian: Aldatma, kontrol ve korku mirasının gerçek varisi kim?"
    t[3843809020]="Wrathion: Yani bir şey buldunuz."
    t[1697636413]="Scalecommander Emberthal: Bulduk. Ve yok ettim."
    t[3353899137]="Sabellian: Hiç hakkın yoktu!"
    t[3964837988]="Scalecommander Emberthal: Her hakkım vardı."
    t[3958820374]="Scalecommander Emberthal: O cihaz var oldukça halkım asla özgür olamazdı."
    t[8642486]="Wrathion: Ne yaptı?"
    t[2874609809]="Ebyssian: Siz ikisi de küstah yavrular gibi didişirken, o halkı için doğru olanı yaptı."
    t[2034817431]="Ebyssian: Geçmişi bırakın."
    t[2031939027]="Ebyssian: Filonuz sizi burada ve şimdiye ihtiyaç duyuyor."
    t[672493778]="Ebyssian: Neyi koruduklarını görelim..."
    t[333319648]="Sabellian: O devasa djaradinler..."
    t[3499837323]="Sabellian: Waking Shores'da karşılaştığımız her şeyin ötesindeler."
    t[1334784861]="Ebyssian: Onlar djaradin yaşlıları. Sadece ejderha avcıları değil, tüm soyları yok edenler."
    t[2064616100]="Sabellian: Şuraya bak!"
    t[3677290025]="Sabellian: Görünüşe göre o hala uyuyor."
    t[285078550]="Ebyssian: Ve Primalistler onu uyandırıyor. Onları durdurmalıyız. Çabuk ol."
    t[3047724085]="Sabellian: Bekle. Hissediyor musun?"
    t[1063324437]="Sabellian: Lavın içine işleyen o alev..."
    t[3839841074]="Sabellian: Acaba..."
    t[3828312682]="Sabellian: Gölgealevi. Neltharion'u deliliğe sürükleyen zehir."
    t[908536146]="Ebyssian: Buna bir son vermeliyiz. Bu yozlaşmanın yayılmasına izin verilemez."
    t[3104388138]="Sabellian: O da ne? İşte orada! Kalderanın içinde."
    t[2723568535]="Ebyssian: Fyrakk!"
    t[320770120]="Sabellian: O... tüketiyor..."
    t[3389702407]="Sabellian: Gölgealevini mi?!"
    t[940535271]="Fyrakk: Ejderhaların kanını kokluyorum..."
    t[1356157180]="Fyrakk: Defolun siz kurtçuklar!"
    t[2281746144]="Sabellian: Ahhhhhhhhhh!"
    t[1244587661]="Ebyssian: Sabellian yaralandı! Şampiyon! Kaçmalıyız!"
    t[2389708243]="Fyrakk: Uçun gidin küçük ejderhalar."
    t[1715553017]="Fyrakk: Sizin sürünüzün kontrol edemediği şeye ben hükmedeceğim."
    t[3416128063]="Fyrakk: BU GÜÇ... ARTIK... BENİM!"
    t[209238592]="Fyrakk: BOYUNDURUKTAN KALKIN, DJARADİN YAŞLILARI!"
    t[1557609682]="Ebyssian: Augh! -- Burada tutunamayız!"
    t[1807084323]="Fyrakk: Yaşlı Igira! Neltharion'ın o çocuğunun kaçmasına izin verme!"
    t[2755789090]="Igira: Argh!"
    t[1349260232]="Ebyssian: Ahhhhhhh!"
    t[1447396741]="[Alexstrasza] Çok yakında,"
    t[3869446815]="Azeroth rüyasından"
    t[2272155196]="bir umut sembolü çıkaracak"
    t[1411335045]="ve hep birlikte onu koruyacağız."
    t[2077866392]="Fyrakk: Bak kardeşim!"
    t[209540833]="Fyrakk: Yeni müttefiklerimizin yakıcı gücü."
    t[1380070678]="Vyranoth: Bu yaratığa ne yaptınız?"
    t[3040694577]="Fyrakk: O yaşayan alevle dolduruldu."
    t[3111051807]="Fyrakk: Onların değerli dünya ağacının kalbine aşılayacağımız alevin ta kendisi."
    t[1270976129]="Fyrakk: Onların değerli dünya ağacının kalbine aşılayacağımız alevin ta kendisi."
    t[1503127722]="Vyranoth: Iridikron onu aşağılık bir iğrençliğe dönüştürmemizi değil,"
    t[2356243781]="Vyranoth:  Aspect'leri ödüllerinden mahrum bırakmamızı emretti."
    t[2823727706]="Fyrakk: Iridikron artık burada değil."
    t[2298119596]="Fyrakk: Ayrıca, beni özgür bırakan da o."
    t[1554232923]="Fyrakk: Gölge alevinin derinliklerinden içmem için bana kim yalvardı."
    t[2740512811]="Fyrakk: Bu savaşı kazanmak için neyin gerekli olduğunu biliyordu."
    t[453861505]="Vyranoth: Dünyayı titanların müdahalesinden kurtarmak için birlikte silahlandık."
    t[732665337]="Vyranoth: Bu benim savaşım."
    t[2706934932]="Vyranoth: Aradığım zafer bu."
    t[2616168898]="Fyrakk: (homurdanır)"
    t[3095210250]="Fyrakk: Zafere ulaşamayız"
    t[4257590830]="Fyrakk: Zafere ulaşamayız"
    t[917545033]="Fyrakk: Ellerimiz senin ideallerinle bağlıyken!"
    t[3849782022]="Wrathion: Durum çok vahim Kraliçe Alexstrasza."
    t[291125731]="Ebyssian: Fyrakk'ı aşağıdaki büyük kazana, elemental ateş kaynağına kadar takip ettik."
    t[594108781]="Sabellian: İçindeki enerjileri tüketti ve gölge alevine bürünerek ortaya çıktı."
    t[793213892]="Alexstrasza the Life-Binder: Gölge Alevi. Seni onun yozlaşmasına kaptırma riskini alamayız."
    t[433845506]="Alexstrasza the Life-Binder: Diğer uçuşlar Fyrakk'ı avlayacak ve Güneşli Alev'i durdurmak için çalışacak."
    t[3892592409]="Alexstrasza the Life-Binder: Zaralek'e geri dönemezsin."
    t[3660187044]="Ebyssian: Saygılarımla, Life-Binder, o yozlaşmaya düşen Deathwing'di."
    t[2081308222]="Ebyssian: Aşağıda yatanlara direnecek gücümüz olduğuna inanıyorum."
    t[4078163511]="Alexstrasza the Life-Binder: Hepiniz mi?"
    t[1667148395]="Ebyssian: Bu... bizim savaşımız."
    t[2744487819]="Ebyssian: Dünyaya siyah dragonflight'ın sorumluluklarını taşıyabileceği gösterilmeli."
    t[3679223472]="Alexstrasza the Life-Binder: Pekala. Hazır olduğunuzda, Zaralek'e dönün."
    t[3716513629]="Alexstrasza the Life-Binder: Dünya Gardiyanı'nın gerçek ruhu sana rehberlik etsin."
    t[1588609937]="Sabellian: Eğer uçuşa hizmet etmeleri sağlanabilirse, bu yılan yaratıklar faydalı olabilir."
    t[4212603311]="Wrathion: Onlar yaratık değil, Sabellian; onlar bizim akrabalarımız."
    t[1985976787]="Sabellian: Onlar babamın başarısız deneyleri, başka bir şey değil."
    t[1306685262]="Sabellian: Savaş alanı için yem."
    t[2352588052]="Wrathion: Nasıl yaratıldığımız bizi tanımlamaz."
    t[1457880218]="Wrathion: Yoksa ben de senin için sadece yem miyim?"
    t[1379931691]="Sabellian: Evet. Sen de tam olarak öylesin."
    t[1783920073]="Wrathion: Yanılıyorsun."
    t[3295773046]="Ebyssian: Kaderlerinizin birbirlerine bağlı olduğunu görmüyor musunuz?"
    t[2847406740]="Ebyssian: İstediğin kadar inkar et, o senin kardeşin, sen de onun."
    t[3658784754]="Ebyssian: Çok geç olmadan birlikte uçmayı ya da başarısız olmayı öğrenmesi gereken iki kanat."
    t[759227075]="Scalecommander Sarkareth: Çağrısına kulak vereceğim!"
    t[183397001]="Emberthal: Öyleyse seçimini yaptın."
    t[805318320]="Sabellian: O fanatiğin laboratuvarı ele geçirmesine izin veremeyiz."
    t[3914433714]="Wrathion: Bana neden bakıyorsunuz? Haydi gidelim!"
    t[178493099]="Ebyssian: Onu... takip etmeyecek misin?"
    t[3773581794]="Emberthal: Adalet karşısına çıkacağını biliyorum ama..."
    t[4219504011]="Emberthal: Kayıp ve kendi soyumla savaşmaktan yoruluyorum. Ama sen..."
    t[2960566393]="Ebyssian: Bu ikisi bununla baş başa kalmalı. Umarım... peşinden giderken..."
    t[4196880140]="Ebyssian: Sonunda Neltharion'un mirasının sadece ölüm olduğunu göreceklerdir."
    t[2069082892]="Emberthal: O zaman henüz bu kaderin pençesine düşmemiş dracthyr'ları bulalım."
    t[2664402387]="Ebyssian: Yolu göster Emberthal."
    t[3454629897]="Scalecommander Sarkareth: Ben... sadık askerindim baba."
    t[3858365839]="Scalecommander Sarkareth: Mirasını yüceltmedim mi?"
    t[669070698]="Scalecommander Sarkareth: Her şey sadece... bir yanılsama mıydı?"
    t[2613054702]="Scalecommander Sarkareth: Boş... vaatler..."
    t[481278213]="Scalecommander Sarkareth: bizi sadece..."
    t[3555907713]="Scalecommander Sarkareth: yok oluşa... götürdü..."
    t[139234729]="Emberthal: Adı sonsuza dek anılsın."
    t[3593398825]="Sabellian: Yaptıklarından sonra neden ona bu kadar saygılı davranıyorsun?"
    t[1935676419]="Emberthal: O bir dracthyr'dı ve anısı bir ders olacaktır."
    t[199267022]="Emberthal: Halkımızın iyileşmesine yardımcı olmak yerine, birçok insanı umutsuzluğa ve yıkıma sürükledi,"
    t[1066496101]="Emberthal: Neltharion'un gücünün yanılsamasının peşinden koştu."
    t[3277833481]="Ebyssian: Keşke Sarkareth, Deathwing'in trajedisini yüreğine alıp,"
    t[1768856192]="Ebyssian: mirasının çok önceleri zehirlendiğini anlasaydı."
    t[2781273836]="Emberthal: Dracthyr'ların kendi yolunu çizme zamanı geldi."
    t[2639081286]="Ebyssian: Nereye ulaşmasını umuyorsun?"
    t[3723402306]="Emberthal: Bizi rahatsız eden geçmişin gölgelerinden uzakta,"
    t[541602036]="Emberthal: kendi mirasımızı inşa etmek için özgür bir geleceğe."
    t[1548366214]="Emberthal: Bana inanmayı ilham verdiğin bir geleceğe, Ebyssian."
    t[1016323927]="Ebyssian: En acı verici anların bile öğreteceği şeyler vardır."
    t[450617120]="Sabellian: Neltharion benim öğretmenimdi. Babam ve komutanımdı."
    t[189052379]="Sabellian: Uçuşa onun gibi liderlik etmeyi hedefledim,"
    t[469956230]="Sabellian: anlayamadım... ya da belki de istemedim..."
    t[1258256493]="Sabellian: vizyonunun gerçek kötülüğünü kabul etmeyi."
    t[2124140000]="Wrathion: Neltharion'u hiç tanımadım. Sadece Deathwing'i."
    t[1875854542]="Wrathion: Kabuslarıma musallat olan. Onun kadar çarpık olacağımdan emin olarak kendini gösteren."
    t[4119965459]="Sabellian: Sen öyle biri değilsin... kardeşim."
    t[1992703054]="Wrathion: Kaderimin, uçuşumuzu geleceğine yönlendirmek olduğunu düşünmüştüm."
    t[3162094667]="Wrathion: Ve yapacağım, ama sadece kendim olarak... bir Aspect olarak değil."
    t[1653684154]="Sabellian: Ben de o görevi aramayacağım."
    t[4004427591]="Emberthal: Görünüşe göre saklanma günlerin bir daha asla geri gelmeyecek şekilde sona erdi."
    t[1359626823]="Ebyssian: Ben... alçakgönüllü biriyim."
    t[2200800155]="Ebyssian: Bana duyduğunuz güven ve inanç her adımımı yönlendirsin."
    t[292860944]="Ebyssian: Bugün, içimizde şüphe ve utanç ekmeye çalışan tüm gölgelerden çıkıyoruz."
    t[1818361543]="Ebyssian: Siyah Dragonflight mirası bizim yaratmamız için."
    t[4129405940]="Alexstrasza: Büyük kahramanlık ve direnç sayesinde, Aberrus tehdidi bastırıldı."
    t[437319677]="Alexstrasza: Bedenleşmişler, düşmüş kardeşimizin anısını bir silah olarak kullanmaya çalıştılar."
    t[2449507937]="Alexstrasza: Bizi bölmek, birbirimize karşı çevirmek ve kararlılığımızı zayıflatmak için."
    t[1172855646]="Alexstrasza: Başaramadılar."
    t[2863198587]="Alexstrasza: Bu gölgelerle yüzleşmek bizi sadece daha güçlü kıldı."
    t[1134907791]="Alexstrasza: Şimdi bize bakın."
    t[1478200433]="Alexstrasza: Uzun zaman sonra ilk kez, BEŞ Aspect, eski görevimizi bir kez daha üstlenecek,"
    t[3870205453]="Alexstrasza: ve her fırsatta bize yardım eden ölümlü şampiyonların yanında duracak."
    t[2443837471]="[metalik ses]"
    t[1639859254]="O inatçı alev yaklaşıyor,"
    t[1805006792]="Zalim Igira: Galok. Avından döndün."
    t[3591509600]="Zalim Igira: Sana verdiğim silahların etkili olduğuna inanıyorum."
    t[3959672448]="Galok Wingslicer:<homurdanma>"
    t[3036722815]="Brathia:"
    t[3157596948]="Zalim Igira: Güzel."
